    auto& bank = regs_.at(warp_slot).freg_file.at(rdest.idx);
    DPH(2, "Dest Reg: " << rdest << "={");
    for (uint32_t t = 0; t < num_threads; ++t) {
      if (t) DPN(2, ", ");
      if (!trace->tmask.test(t)) {
        DPN(2, "-");
        continue;
      }
      uint64_t cur = bank.at(t);
      uint64_t incoming = trace->dst_data[t].u64;
